using System.Text.Json.Nodes; using Jsonata.Net.Core.Evaluation; using Jsonata.Net.Core.Exceptions; namespace Jsonata.Net.Core.AstNodes; public sealed class ConditionalNode : AstNode {     public AstNode Condition { get; }     public AstNode ThenExpression { get; }     public AstNode ElseExpression { get; }     public ConditionalNode(AstNode condition, AstNode thenExpr, AstNode elseExpr) {         this.Condition = condition;         this.ThenExpression = thenExpr;         this.ElseExpression = elseExpr;     }     public override Sequence Evaluate(JsonNode? input, EvaluationContext context) {         Sequence condResultSeq = this.Condition.Evaluate(input, context);         if (Sequence.IsTruthy(condResultSeq)) {             return this.ThenExpression.Evaluate(input, context);         } else {             return this.ElseExpression.Evaluate(input, context); /* ElseExpression guaranteed non-null by parser for ternary */         }     } }
